from math import gamma, pi


def unit_ball_volume(n: int) -> float:
    return pi ** (n / 2) / gamma(n / 2 + 1)


def main() -> None:
    vols = [(n, unit_ball_volume(n)) for n in range(1, 21)]
    peak = max(vols, key=lambda t: t[1])
    for n, v in vols:
        tag = '  <-- peak' if n == peak[0] else (
              '  <-- 4D (pi^2/2)' if n == 4 else '')
        print(f'omega_{n:>2} = {v:.6f}{tag}')
    print(f'\nMaximal unit-ball volume at dimension n = {peak[0]}')
    assert abs(unit_ball_volume(4) - pi ** 2 / 2) < 1e-12


if __name__ == '__main__':
    main()

import cmath
from math import pi
from typing import List, Tuple

Pt3 = Tuple[float, float, float]


def hopf(z: complex, w: complex) -> Tuple[complex, float]:
    return (2 * z * w.conjugate(), abs(z) ** 2 - abs(w) ** 2)


def fibre_point(z: complex, w: complex, phi: float) -> Tuple[complex, complex]:
    lam = cmath.exp(1j * phi)
    return lam * z, lam * w


def stereo(z: complex, w: complex) -> Pt3:
    # project S^3 (minus a pole) from (0,0,0,1) into R^3
    x1, x2, x3, x4 = z.real, z.imag, w.real, w.imag
    d = 1.0 - x4
    return (x1 / d, x2 / d, x3 / d)


def gauss_linking(c1: List[Pt3], c2: List[Pt3]) -> float:
    total = 0.0
    n1, n2 = len(c1), len(c2)
    for i in range(n1):
        a, an = c1[i], c1[(i + 1) % n1]
        da = tuple(an[k] - a[k] for k in range(3))
        for j in range(n2):
            b, bn = c2[j], c2[(j + 1) % n2]
            db = tuple(bn[k] - b[k] for k in range(3))
            r = tuple(a[k] - b[k] for k in range(3))
            rn = sum(x * x for x in r) ** 1.5
            if rn < 1e-12:
                continue
            cx = (da[1] * db[2] - da[2] * db[1],
                  da[2] * db[0] - da[0] * db[2],
                  da[0] * db[1] - da[1] * db[0])
            total += sum(cx[k] * r[k] for k in range(3)) / rn
    return total / (4 * pi)


def circle_of(z0: complex, w0: complex, n: int) -> List[Pt3]:
    return [stereo(*fibre_point(z0, w0, 2 * pi * j / n)) for j in range(n)]


def main() -> None:
    # two different points of S^3 with distinct Hopf images
    c1 = circle_of(complex(0.8, 0.0), complex(0.0, 0.6), 400)
    c2 = circle_of(complex(0.0, 0.6), complex(0.8, 0.0), 400)
    lk = gauss_linking(c1, c2)
    print(f'Estimated Gauss linking number of two Hopf fibres: {lk:.3f}')
    print('(Expected: 1 -- the Hopf link)')


if __name__ == '__main__':
    main()

