function FACE_COUNT(n, k):
    return 2^(n-k) * BINOMIAL(n, k)

function CUBE_EULER(n):        # alternating sum over all faces
    s <- 0
    for k in 0..n:
        s <- s + (-1)^k * FACE_COUNT(n, k)
    return s               # provably equals 1

function BOUNDARY_EULER(n):    # drop the top (solid) cell
    return CUBE_EULER(n) - (-1)^n   # equals 1 - (-1)^n

