from math import comb


def face_count(n: int, k: int) -> int:
    """Number of k-faces of the n-cube: 2^(n-k) * C(n, k)."""
    return 2 ** (n - k) * comb(n, k)


def cube_euler(n: int) -> int:
    """Alternating face count of the solid n-cube (always 1)."""
    return sum((-1) ** k * face_count(n, k) for k in range(n + 1))


def boundary_euler(n: int) -> int:
    """Euler characteristic of the boundary (n-1)-sphere: 1 - (-1)^n."""
    return sum((-1) ** k * face_count(n, k) for k in range(n))


assert [face_count(4, k) for k in range(5)] == [16, 32, 24, 8, 1]
assert all(cube_euler(n) == 1 for n in range(1, 20))
assert all(boundary_euler(n) == 1 - (-1) ** n for n in range(1, 20))

