function HOPF(z, w):
    return (2 * z * conj(w), |z|^2 - |w|^2)

function HOPF_FIBRE(z, w, N):   # circle over base point HOPF(z,w)
    fibre <- []
    for j in 0..N-1:
        phi <- 2*pi*j / N
        lambda <- exp(i * phi)          # |lambda| = 1
        fibre.append((lambda*z, lambda*w))
    return fibre        # all map to the same HOPF(z,w)

function ROT4(theta, (a,b,c,d)):
    return (a*cos t - d*sin t, b, c, a*sin t + d*cos t)   # t = theta

function ROT23(phi, (a,b,c,d)):
    return (a, b*cos p - c*sin p, b*sin p + c*cos p, d)   # p = phi

function COMPOSE(theta, phi, p):     # commuting isoclinic pair
    return ROT23(phi, ROT4(theta, p)) == ROT4(theta, ROT23(phi, p))

