from math import cos, sin
from typing import Tuple

Vec4 = Tuple[float, float, float, float]


def rot4(theta: float, p: Vec4) -> Vec4:
    """Rotate the (axis 1, axis 4) plane by angle theta."""
    a, b, c, d = p
    return (a * cos(theta) - d * sin(theta), b, c,
            a * sin(theta) + d * cos(theta))


def rot23(phi: float, p: Vec4) -> Vec4:
    """Rotate the (axis 2, axis 3) plane by angle phi."""
    a, b, c, d = p
    return (a, b * cos(phi) - c * sin(phi),
            b * sin(phi) + c * cos(phi), d)


def norm_sq(p: Vec4) -> float:
    return sum(x * x for x in p)


p = (1.0, 2.0, -0.5, 3.0)
assert abs(norm_sq(rot4(1.1, p)) - norm_sq(p)) < 1e-12
# the two plane-rotations commute (isoclinic doubling)
lhs, rhs = rot23(0.7, rot4(1.1, p)), rot4(1.1, rot23(0.7, p))
assert max(abs(a - b) for a, b in zip(lhs, rhs)) < 1e-12

